SOURCES = {
    'numeric_utils': '"""Numerically stable helpers and domain limits for market-data calculations."""\n\nimport math\n\n# Wide fail-closed bound. Real 8h funding is orders of magnitude smaller,\n# while values outside this range can overflow annualization despite being\n# finite IEEE-754 inputs.\nMAX_ABS_FUNDING_RATE = 1.0\n\n\ndef scaled_mean(values: list[float]) -> float:\n    """Return a finite mean without overflowing while summing finite values."""\n    if not values:\n        raise ValueError("scaled_mean requires at least one value")\n    scale = max(abs(value) for value in values)\n    if scale == 0:\n        return 0.0\n    return scale * (math.fsum(value / scale for value in values) / len(values))\n',
    'scorer': '#!/usr/bin/env python3\n"""\nCrypto Regime Analyzer - Composite Scoring Engine\n\nCombines 6 component scores into a weighted composite (0-100).\nScore direction: 100 = Risk-on health, 0 = Critical risk-off.\n\nComponent Weights:\n1. BTC Trend Structure:            25%\n2. Alt Breadth Participation:      20%\n3. BTC Dominance Regime:           15%\n4. Perpetual Funding Regime:       15%\n5. Drawdown & Volatility Position: 15%\n6. Momentum Thrust / Washout:      10%\nTotal: 100%\n\nWhen a component has data_available=False, its weight is proportionally\nredistributed only when at least four components representing at least 65%\nof the original model weight remain. Sparser inputs fail closed as UNKNOWN.\n\nRegime Zone Mapping (100 = Risk-on):\n  80-100: RISK_ON  - Broad risk-on conditions observed\n  40-79:  NEUTRAL  - Mixed conditions; no strong regime conclusion\n  0-39:   RISK_OFF - Defensive market conditions observed\n"""\n\nCOMPONENT_WEIGHTS = {\n    "btc_trend": 0.25,\n    "alt_breadth": 0.20,\n    "dominance": 0.15,\n    "funding": 0.15,\n    "drawdown_vol": 0.15,\n    "momentum_thrust": 0.10,\n}\n\nCOMPONENT_LABELS = {\n    "btc_trend": "BTC Trend Structure",\n    "alt_breadth": "Alt Breadth Participation",\n    "dominance": "BTC Dominance Regime",\n    "funding": "Perpetual Funding Regime",\n    "drawdown_vol": "Drawdown & Volatility Position",\n    "momentum_thrust": "Momentum Thrust / Washout",\n}\n\nMIN_AVAILABLE_COMPONENTS = 4\nMIN_AVAILABLE_WEIGHT = 0.65\n\nZONES = [\n    (80, "RISK_ON", "Broad risk-on conditions observed; review risk limits before decisions"),\n    (40, "NEUTRAL", "Mixed conditions observed; no strong regime conclusion"),\n    (0, "RISK_OFF", "Defensive market conditions observed; review existing risk controls"),\n]\n\n\ndef calculate_composite_score(components: dict) -> dict:\n    """\n    Weighted composite over available components.\n\n    Args:\n        components: {component_id: result dict with score + data_available}.\n\n    Returns:\n        Dict with composite score, zone, guidance, and effective weights.\n    """\n    available = {\n        cid: comp\n        for cid, comp in components.items()\n        if cid in COMPONENT_WEIGHTS and comp.get("data_available", False)\n    }\n    total_weight = sum(COMPONENT_WEIGHTS[cid] for cid in available)\n    if len(available) < MIN_AVAILABLE_COMPONENTS or total_weight < MIN_AVAILABLE_WEIGHT:\n        return {\n            "score": None,\n            "zone": "UNKNOWN",\n            "guidance": (\n                "Insufficient component coverage for a regime classification "\n                f"({len(available)}/{len(COMPONENT_WEIGHTS)} components, "\n                f"{total_weight:.0%} model weight)"\n            ),\n            "effective_weights": {},\n            "components_available": len(available),\n            "components_total": len(COMPONENT_WEIGHTS),\n            "available_weight": round(total_weight, 4),\n        }\n\n    effective = {cid: COMPONENT_WEIGHTS[cid] / total_weight for cid in available}\n    score = sum(available[cid]["score"] * w for cid, w in effective.items())\n    score = round(max(0.0, min(100.0, score)), 1)\n\n    zone, guidance = ZONES[-1][1], ZONES[-1][2]\n    for threshold, z, g in ZONES:\n        if score >= threshold:\n            zone, guidance = z, g\n            break\n\n    return {\n        "score": score,\n        "zone": zone,\n        "guidance": guidance,\n        "effective_weights": {k: round(v, 4) for k, v in effective.items()},\n        "components_available": len(available),\n        "components_total": len(COMPONENT_WEIGHTS),\n        "available_weight": round(total_weight, 4),\n    }\n',
    'calculators': '',
    'calculators.alt_breadth_calculator': '#!/usr/bin/env python3\n"""\nComponent 2: Alt Breadth Participation (Weight: 20%)\n\nMeasures how broadly the altcoin market participates in the trend, the\ncrypto analog of "% of stocks above the 200DMA". Narrow markets (BTC up,\nalts dead) are late-cycle or defensive; broad participation confirms\nrisk-on.\n\nInput: dict of {symbol: [daily closes oldest -> newest]} for the tracked\nalt universe (BTC excluded upstream). Coins with insufficient history are\nskipped and reported.\n\nScoring (100 = broad participation):\n  pct_above_200dma drives the base score:\n    >= 80% -> 95    >= 65% -> 80    >= 50% -> 65\n    >= 35% -> 45    >= 20% -> 25    <  20% -> 10\n\n  50DMA confirmation modifier:\n    pct_above_50dma >= pct_above_200dma + 15pts -> +5  (fresh thrust)\n    pct_above_50dma <= pct_above_200dma - 15pts -> -5  (rolling over)\n"""\n\nfrom numeric_utils import scaled_mean\n\nMIN_HISTORY = 200\nMIN_UNIVERSE = 5\n\n\ndef _pct_above_sma(series_map: dict, window: int) -> tuple:\n    above, counted, skipped = 0, 0, []\n    for symbol, closes in series_map.items():\n        if not closes or len(closes) < window:\n            skipped.append(symbol)\n            continue\n        counted += 1\n        if closes[-1] > scaled_mean(closes[-window:]):\n            above += 1\n    pct = (above / counted * 100) if counted else 0.0\n    return pct, counted, skipped\n\n\ndef _base_score(pct_200: float) -> int:\n    if pct_200 >= 80:\n        return 95\n    if pct_200 >= 65:\n        return 80\n    if pct_200 >= 50:\n        return 65\n    if pct_200 >= 35:\n        return 45\n    if pct_200 >= 20:\n        return 25\n    return 10\n\n\ndef calculate_alt_breadth(alt_series: dict) -> dict:\n    """\n    Score altcoin breadth participation.\n\n    Args:\n        alt_series: {symbol: [daily closes oldest -> newest]}.\n\n    Returns:\n        Dict with score, signal, data_available, and breadth details.\n    """\n    alt_series = alt_series or {}\n    eligible = {\n        symbol: closes\n        for symbol, closes in alt_series.items()\n        if closes and len(closes) >= MIN_HISTORY\n    }\n    skipped = [symbol for symbol in alt_series if symbol not in eligible]\n    pct_200, counted, _ = _pct_above_sma(eligible, MIN_HISTORY)\n    if counted < MIN_UNIVERSE:\n        return {\n            "score": 50,\n            "signal": f"NO DATA: Only {counted} alts with >= {MIN_HISTORY}d history "\n            f"(need {MIN_UNIVERSE})",\n            "data_available": False,\n        }\n\n    pct_50, _, _ = _pct_above_sma(eligible, 50)\n    score = _base_score(pct_200)\n    modifier = ""\n    if pct_50 >= pct_200 + 15:\n        score += 5\n        modifier = "; short-term thrust (50DMA breadth leading)"\n    elif pct_50 <= pct_200 - 15:\n        score -= 5\n        modifier = "; short-term breadth rolling over"\n    score = max(0, min(100, score))\n\n    return {\n        "score": score,\n        "signal": f"{pct_200:.0f}% of {counted} tracked alts above 200DMA "\n        f"({pct_50:.0f}% above 50DMA){modifier}",\n        "data_available": True,\n        "pct_above_200dma": round(pct_200, 1),\n        "pct_above_50dma": round(pct_50, 1),\n        "universe_size": counted,\n        "skipped": skipped,\n    }\n',
    'calculators.btc_trend_calculator': '#!/usr/bin/env python3\n"""\nComponent 1: BTC Trend Structure (Weight: 25%)\n\nBitcoin is the reserve asset of the crypto market: alt regimes almost never\nstay risk-on while BTC trend structure is broken. This component scores the\nhealth of BTC\'s primary trend using daily closes.\n\nInput: list of BTC daily closes, oldest first (>= 220 observations for full\nscoring; degrades gracefully below that).\n\nScoring (100 = healthy risk-on trend):\n  Base score from price vs 50DMA / 200DMA structure:\n    price > 50DMA > 200DMA (bull stack)      -> 90\n    price > 200DMA, price < 50DMA (pullback) -> 65\n    price < 50DMA and 50DMA > 200DMA         -> 55 (uses stack, price below both)\n    price > 50DMA, price < 200DMA (recovery) -> 45\n    price < 50DMA < 200DMA (bear stack)      -> 15\n\n  200DMA slope modifier (20-day lookback):\n    rising  -> +10\n    flat    ->   0\n    falling -> -10\n\n  Cross proximity modifier:\n    |50DMA - 200DMA| / 200DMA < 1.5% -> signal notes an imminent cross\n    (no score change; informational)\n\nAn exactly flat price/MA structure is neutral (50), not a bear stack.\nScore is clamped to [0, 100].\n"""\n\nimport math\n\nfrom numeric_utils import scaled_mean\n\nSLOPE_LOOKBACK = 20\nMIN_FULL_HISTORY = 200 + SLOPE_LOOKBACK\nCROSS_PROXIMITY_PCT = 0.015\nFLAT_REL_TOLERANCE = 1e-12\n\n\ndef _sma(values: list, window: int) -> float:\n    return scaled_mean(values[-window:])\n\n\ndef calculate_btc_trend(closes: list) -> dict:\n    """\n    Score BTC primary trend structure.\n\n    Args:\n        closes: BTC daily closing prices sorted oldest -> newest.\n\n    Returns:\n        Dict with score, signal, data_available, and trend details.\n    """\n    if not closes or len(closes) < MIN_FULL_HISTORY:\n        return {\n            "score": 50,\n            "signal": f"NO DATA: Need >= {MIN_FULL_HISTORY} daily closes for BTC trend structure",\n            "data_available": False,\n        }\n\n    price = closes[-1]\n    ma50 = _sma(closes, 50)\n    ma200 = _sma(closes, 200)\n    ma200_prev = scaled_mean(closes[-(200 + SLOPE_LOOKBACK) : -SLOPE_LOOKBACK])\n    if math.isclose(ma200, ma200_prev, rel_tol=FLAT_REL_TOLERANCE, abs_tol=0.0):\n        ma200_direction = "flat"\n    elif ma200 > ma200_prev:\n        ma200_direction = "rising"\n    else:\n        ma200_direction = "falling"\n    ma200_rising = ma200_direction == "rising"\n\n    is_flat_structure = all(\n        math.isclose(value, ma200, rel_tol=FLAT_REL_TOLERANCE, abs_tol=0.0)\n        for value in (price, ma50)\n    )\n    if is_flat_structure:\n        base, structure = 50, "FLAT (price = 50DMA = 200DMA)"\n    elif price > ma50 > ma200:\n        base, structure = 90, "BULL STACK (price > 50DMA > 200DMA)"\n    elif price > ma200 and price <= ma50 and ma50 > ma200:\n        base, structure = 65, "BULL PULLBACK (price between 200DMA and 50DMA)"\n    elif price <= ma200 and price <= ma50 and ma50 > ma200:\n        base, structure = 55, "STACK INTACT, PRICE BELOW (deep pullback / early break)"\n    elif price > ma50 and ma50 <= ma200:\n        base, structure = 45, "RECOVERY ATTEMPT (price above 50DMA, stack still bearish)"\n    else:\n        base, structure = 15, "BEAR STACK (price < 50DMA < 200DMA)"\n\n    slope_modifier = (\n        10 if ma200_direction == "rising" else -10 if ma200_direction == "falling" else 0\n    )\n    score = base + slope_modifier\n    score = max(0, min(100, score))\n\n    signal = f"{structure}; 200DMA {ma200_direction}"\n    if not is_flat_structure and ma200 > 0 and abs(ma50 - ma200) / ma200 < CROSS_PROXIMITY_PCT:\n        cross = "golden cross" if ma50 <= ma200 and price > ma50 else "cross"\n        signal += f"; 50/200DMA within 1.5% ({cross} watch)"\n\n    return {\n        "score": score,\n        "signal": signal,\n        "data_available": True,\n        "price": round(price, 2),\n        "ma50": round(ma50, 2),\n        "ma200": round(ma200, 2),\n        "ma200_rising": ma200_rising,\n        "ma200_direction": ma200_direction,\n    }\n',
    'calculators.dominance_calculator': '#!/usr/bin/env python3\n"""\nComponent 3: BTC Dominance Regime (Weight: 15%)\n\nBTC dominance direction is only meaningful jointly with BTC\'s own trend:\n\n  BTC trend UP  + dominance FALLING -> capital rotating out the risk curve\n                                        (classic alt-season risk-on)      -> 90\n  BTC trend UP  + dominance RISING  -> BTC-led market, alts lagging\n                                        (constructive but narrow)         -> 65\n  BTC trend DOWN + dominance RISING -> flight to relative safety inside\n                                        crypto (defensive)                -> 30\n  BTC trend DOWN + dominance FALLING-> indiscriminate de-risking or\n                                        stable-rotation (worst regime)    -> 10\n\nExtreme-dominance level modifier:\n  dominance >= 62% -> +5 when BTC trend down (washout / max-fear zone often\n                       precedes bottoms), no change when trend up\n  dominance <= 40% -> -5 when BTC trend up (froth: alts historically\n                       overextended at very low dominance)\n\nInput: list of daily dominance percentages oldest -> newest (>= 31 obs),\nplus btc_trend_up flag from Component 1.\n"""\n\nTREND_LOOKBACK = 30\nHIGH_DOMINANCE = 62.0\nLOW_DOMINANCE = 40.0\nFLAT_BAND = 0.5  # dominance percentage-point change treated as flat\n\n\ndef calculate_dominance_regime(dominance_series: list, btc_trend_up: bool) -> dict:\n    """\n    Score BTC dominance regime jointly with BTC trend direction.\n\n    Args:\n        dominance_series: Daily BTC dominance %, oldest -> newest.\n        btc_trend_up: True when Component 1 shows constructive BTC trend.\n\n    Returns:\n        Dict with score, signal, data_available, and dominance details.\n    """\n    if not dominance_series or len(dominance_series) < TREND_LOOKBACK + 1:\n        return {\n            "score": 50,\n            "signal": f"NO DATA: Need >= {TREND_LOOKBACK + 1} daily dominance points",\n            "data_available": False,\n        }\n\n    current = dominance_series[-1]\n    prior = dominance_series[-(TREND_LOOKBACK + 1)]\n    change = current - prior\n\n    if change > FLAT_BAND:\n        dom_direction = "rising"\n    elif change < -FLAT_BAND:\n        dom_direction = "falling"\n    else:\n        dom_direction = "flat"\n\n    if btc_trend_up:\n        if dom_direction == "falling":\n            score, regime = 90, "ALT ROTATION (BTC up, dominance falling)"\n        elif dom_direction == "rising":\n            score, regime = 65, "BTC-LED (BTC up, dominance rising; alts lagging)"\n        else:\n            score, regime = 75, "BTC UP, dominance flat"\n    else:\n        if dom_direction == "rising":\n            score, regime = 30, "DEFENSIVE (BTC down, dominance rising)"\n        elif dom_direction == "falling":\n            score, regime = 10, "DE-RISKING (BTC down, dominance falling)"\n        else:\n            score, regime = 25, "BTC DOWN, dominance flat"\n\n    modifier = ""\n    if current >= HIGH_DOMINANCE and not btc_trend_up:\n        score += 5\n        modifier = "; dominance at washout extreme (contrarian watch)"\n    elif current <= LOW_DOMINANCE and btc_trend_up:\n        score -= 5\n        modifier = "; dominance at froth extreme (late-cycle caution)"\n    score = max(0, min(100, score))\n\n    return {\n        "score": score,\n        "signal": f"{regime}; dominance {current:.1f}% "\n        f"({change:+.1f}pts / {TREND_LOOKBACK}d){modifier}",\n        "data_available": True,\n        "dominance_pct": round(current, 2),\n        "dominance_change_30d": round(change, 2),\n        "direction": dom_direction,\n    }\n',
    'calculators.drawdown_vol_calculator': '#!/usr/bin/env python3\n"""\nComponent 5: Drawdown & Volatility Position (Weight: 15%)\n\nLocates BTC within its cycle using drawdown from the trailing 1-year high,\nthen adjusts for the realized-volatility regime. Shallow drawdowns with\ncompressed volatility historically precede continuation; deep drawdowns\nwith expanding volatility mark active bear phases.\n\nInput: BTC daily closes oldest -> newest (>= 365 obs for full scoring).\n\nScoring (100 = healthy cycle position):\n  Drawdown from trailing 365d high:\n    <= 10% -> 90    <= 20% -> 75    <= 35% -> 55\n    <= 50% -> 35    <= 65% -> 20    >  65% -> 10 (capitulation zone)\n\n  Volatility modifier (30d realized vol vs its trailing 1y distribution):\n    vol in bottom third of 1y range -> +10 (compression)\n    vol in top third of 1y range    -> -10 (expansion / stress)\n\n  Deep-drawdown contrarian floor: when drawdown > 65% AND volatility is in\n  the top third (capitulation), score floors at 15 rather than falling\n  further; extreme readings are where forward returns start improving.\n"""\n\nimport math\n\nMIN_HISTORY = 365\nVOL_WINDOW = 30\n\n\ndef _drawdown_score(dd: float) -> int:\n    if dd <= 0.10:\n        return 90\n    if dd <= 0.20:\n        return 75\n    if dd <= 0.35:\n        return 55\n    if dd <= 0.50:\n        return 35\n    if dd <= 0.65:\n        return 20\n    return 10\n\n\ndef _realized_vol(closes: list, window: int) -> float:\n    # log(current) - log(previous) is algebraically identical to\n    # log(current / previous), but does not overflow/underflow when both\n    # prices are finite positive values at opposite IEEE-754 extremes.\n    rets = [\n        math.log(closes[i]) - math.log(closes[i - 1])\n        for i in range(len(closes) - window + 1, len(closes))\n        if closes[i - 1] > 0\n    ]\n    if len(rets) < 2:\n        return 0.0\n    mean = math.fsum(rets) / len(rets)\n    var = math.fsum((r - mean) ** 2 for r in rets) / (len(rets) - 1)\n    return math.sqrt(max(0.0, var)) * math.sqrt(365)\n\n\ndef calculate_drawdown_vol(closes: list) -> dict:\n    """\n    Score BTC cycle position via drawdown and volatility regime.\n\n    Args:\n        closes: BTC daily closes oldest -> newest.\n\n    Returns:\n        Dict with score, signal, data_available, and cycle details.\n    """\n    if not closes or len(closes) < MIN_HISTORY:\n        return {\n            "score": 50,\n            "signal": f"NO DATA: Need >= {MIN_HISTORY} daily closes",\n            "data_available": False,\n        }\n\n    window = closes[-MIN_HISTORY:]\n    high = max(window)\n    price = closes[-1]\n    dd = 1 - (price / high) if high > 0 else 0.0\n    score = _drawdown_score(dd)\n\n    # Volatility percentile within trailing year of rolling 30d vols\n    vols = [\n        _realized_vol(window[: i + 1], VOL_WINDOW)\n        for i in range(VOL_WINDOW, len(window), 7)  # weekly stride for speed\n    ]\n    current_vol = _realized_vol(window, VOL_WINDOW)\n    below = sum(1 for v in vols if v <= current_vol)\n    vol_pctile = below / len(vols) if vols else 0.5\n\n    modifier = ""\n    if vol_pctile <= 1 / 3:\n        score += 10\n        modifier = "; volatility compressed (bottom third of 1y range)"\n    elif vol_pctile >= 2 / 3:\n        score -= 10\n        modifier = "; volatility elevated (top third of 1y range)"\n\n    if dd > 0.65 and vol_pctile >= 2 / 3:\n        score = max(score, 15)\n        modifier += "; capitulation-zone contrarian floor applied"\n\n    score = max(0, min(100, score))\n    return {\n        "score": score,\n        "signal": f"Drawdown {dd * 100:.1f}% from 1y high{modifier}",\n        "data_available": True,\n        "drawdown_pct": round(dd * 100, 2),\n        "realized_vol_30d": round(current_vol, 4),\n        "vol_percentile_1y": round(vol_pctile, 2),\n    }\n',
    'calculators.funding_calculator': '#!/usr/bin/env python3\n"""\nComponent 4: Perpetual Funding Regime (Weight: 15%)\n\nPerp funding rates proxy aggregate leverage positioning. The scoring is\ndeliberately contrarian at the extremes and trend-friendly in the middle:\n\n  Average 8h funding across tracked majors (annualized shown in signal):\n    strongly negative (<= -0.010%)          -> 80  (washed out; shorts pay)\n    mildly negative (-0.010% .. 0%)         -> 65  (skeptical positioning)\n    neutral-positive (0% .. +0.010%)        -> 75  (healthy, near baseline)\n    warm (+0.010% .. +0.030%)               -> 55  (leverage building)\n    hot (+0.030% .. +0.060%)                -> 30  (crowded longs)\n    extreme (> +0.060%)                     -> 10  (euphoric leverage;\n                                                    liquidation-cascade risk)\n\nBaseline note: Binance\'s default funding is +0.010% per 8h, so "neutral"\nclusters slightly positive by construction.\n\nInput: dict of {symbol: latest 8h funding rate as decimal} e.g.\n{"BTCUSDT": 0.0001} for +0.010%. Rates outside [-1, 1] are rejected as\ninvalid data before averaging or annualizing.\n"""\n\nimport math\n\nfrom numeric_utils import MAX_ABS_FUNDING_RATE, scaled_mean\n\nMIN_SYMBOLS = 2\n\n\ndef calculate_funding_regime(funding_map: dict) -> dict:\n    """\n    Score perp funding regime from latest 8h rates.\n\n    Args:\n        funding_map: {symbol: funding rate as decimal per 8h period}.\n\n    Returns:\n        Dict with score, signal, data_available, and funding details.\n    """\n    raw_rates = [rate for rate in (funding_map or {}).values() if rate is not None]\n    invalid = [\n        rate\n        for rate in raw_rates\n        if isinstance(rate, bool)\n        or not isinstance(rate, (int, float))\n        or not math.isfinite(rate)\n        or abs(rate) > MAX_ABS_FUNDING_RATE\n    ]\n    if invalid:\n        return {\n            "score": 50,\n            "signal": "INVALID DATA: funding rate must be finite and between -1 and 1",\n            "data_available": False,\n        }\n\n    rates = raw_rates\n    if len(rates) < MIN_SYMBOLS:\n        return {\n            "score": 50,\n            "signal": f"NO DATA: Need funding for >= {MIN_SYMBOLS} symbols",\n            "data_available": False,\n        }\n\n    avg = scaled_mean(rates)\n    if avg <= -0.00010:\n        score, label = 80, "WASHED OUT (negative funding; shorts paying longs)"\n    elif avg < 0.0:\n        score, label = 65, "SKEPTICAL (mildly negative funding)"\n    elif avg <= 0.00010:\n        score, label = 75, "NEUTRAL (funding near baseline)"\n    elif avg <= 0.00030:\n        score, label = 55, "WARMING (long leverage building)"\n    elif avg <= 0.00060:\n        score, label = 30, "CROWDED (hot funding; crowded longs)"\n    else:\n        score, label = 10, "EUPHORIC (extreme funding; cascade risk)"\n\n    annualized = avg * 3 * 365 * 100\n    return {\n        "score": score,\n        "signal": f"{label}; avg {avg * 100:.4f}%/8h "\n        f"(~{annualized:.1f}% annualized) across {len(rates)} perps",\n        "data_available": True,\n        "avg_funding_8h": avg,\n        "annualized_pct": round(annualized, 2),\n        "n_symbols": len(rates),\n    }\n',
    'calculators.momentum_thrust_calculator': '#!/usr/bin/env python3\n"""\nComponent 6: Momentum Thrust / Washout (Weight: 10%)\n\nShort-horizon confirmation: what share of the tracked universe (BTC +\nalts) has a positive trailing 30d return. Extremes in either direction\nare informative — broad positive momentum confirms risk-on, while\nnear-total negative momentum marks washouts that often precede\nmean-reversion bounces.\n\nInput: dict of {symbol: [daily closes oldest -> newest]}, >= 31 obs each.\n\nScoring:\n  pct with positive 30d return:\n    >= 85% -> 90 (broad thrust)\n    >= 65% -> 75\n    >= 45% -> 55\n    >= 25% -> 35\n    >= 10% -> 20\n    <  10% -> 35 (washout: contrarian bump vs the 20 a plain mapping gives)\n"""\n\nLOOKBACK = 30\nMIN_UNIVERSE = 5\n\n\ndef calculate_momentum_thrust(series_map: dict) -> dict:\n    """\n    Score universe 30d momentum breadth.\n\n    Args:\n        series_map: {symbol: [daily closes oldest -> newest]}.\n\n    Returns:\n        Dict with score, signal, data_available, and momentum details.\n    """\n    positive, counted = 0, 0\n    for closes in (series_map or {}).values():\n        if not closes or len(closes) < LOOKBACK + 1:\n            continue\n        counted += 1\n        if closes[-1] > closes[-(LOOKBACK + 1)]:\n            positive += 1\n\n    if counted < MIN_UNIVERSE:\n        return {\n            "score": 50,\n            "signal": f"NO DATA: Only {counted} coins with >= {LOOKBACK + 1}d history",\n            "data_available": False,\n        }\n\n    pct = positive / counted * 100\n    if pct >= 85:\n        score, label = 90, "BROAD THRUST"\n    elif pct >= 65:\n        score, label = 75, "POSITIVE"\n    elif pct >= 45:\n        score, label = 55, "MIXED"\n    elif pct >= 25:\n        score, label = 35, "WEAK"\n    elif pct >= 10:\n        score, label = 20, "BROADLY NEGATIVE"\n    else:\n        score, label = 35, "WASHOUT (contrarian: near-total negative momentum)"\n\n    return {\n        "score": score,\n        "signal": f"{label}: {pct:.0f}% of {counted} coins positive over {LOOKBACK}d",\n        "data_available": True,\n        "pct_positive_30d": round(pct, 1),\n        "universe_size": counted,\n    }\n',
}

ORDER = ['numeric_utils', 'scorer', 'calculators'] + sorted(k for k in SOURCES if k.startswith('calculators.'))


def install() -> None:
    """Register the original modules (numeric_utils, scorer, calculators.*) so normal imports work."""
    for name in ORDER:
        if name in sys.modules:
            continue
        mod = types.ModuleType(name)
        mod.__file__ = f'<regime_skill:{name}>'
        if name == 'calculators':
            mod.__path__ = []
        sys.modules[name] = mod
        exec(compile(SOURCES[name], mod.__file__, 'exec'), mod.__dict__)
        if '.' in name:
            setattr(sys.modules['calculators'], name.split('.', 1)[1], mod)
